// 服装用の季節：体感（実際の気候）に合わせる＝3-5春/6-8夏/9-11秋/12-2冬。
// 「季節のたより」や旬の食材は節気ベースのまま。服だけ体感に寄せて“8月に長袖/冬にサンダル”を防ぐ。
function climateSeason(m){ return (m>=3&&m<=5)?'春':(m>=6&&m<=8)?'夏':(m>=9&&m<=11)?'秋':'冬'; }
function getSekki(Y,M,D){
  const md=M*100+D;
  // 1/1〜1/4は前年の冬至期間→冬至扱い
  let cur=SEKKI[SEKKI.length-1]; // 冬至（初期値=年初は冬至の続き）
  for(let i=0;i<SEKKI.length;i++){
    const s=SEKKI[i];
    if(md>=s.m*100+s.d) cur=s; else break;
  }
  return cur;
}
